import time

from .errors import UnknownSession


class MemoryStore:
    def __init__(self, ttl=None, clock=None):
        self._ttl = ttl
        self._clock = clock if clock is not None else time.monotonic
        self._data = {}

    def _expired(self, session_id):
        if self._ttl is None:
            return False
        _, last_touch = self._data[session_id]
        return (self._clock() - last_touch) > self._ttl

    def get(self, session_id):
        if session_id not in self._data or self._expired(session_id):
            raise UnknownSession(session_id)
        return self._data[session_id][0]

    def set(self, session_id, value):
        self._data[session_id] = (value, self._clock())

    def delete(self, session_id):
        if session_id not in self._data:
            raise UnknownSession(session_id)
        del self._data[session_id]

    def touch(self, session_id):
        if session_id not in self._data or self._expired(session_id):
            raise UnknownSession(session_id)
        value, _ = self._data[session_id]
        self._data[session_id] = (value, self._clock())

    def clear(self):
        self._data.clear()

    def keys(self):
        now = self._clock()
        result = []
