```file vp/validate.py
from vp.errors import MissingField, BadType, BadValue


def _matches_type(value, expected_type):
    if isinstance(expected_type, tuple):
        return any(_matches_type(value, t) for t in expected_type)

    if expected_type is bool:
        return isinstance(value, bool)
    if expected_type is int:
        return isinstance(value, int) and not isinstance(value, bool)
    if expected_type is float:
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if expected_type is str:
        return isinstance(value, str)

    return isinstance(value, expected_type)


def _coerce(value, expected_type):
    if expected_type is float and isinstance(value, int) and not isinstance(value, bool):
        return float(value)
    return value


def validate(obj, schema):
    """Validate *obj* against *schema* and return a new dict of coerced values.

    Never mutates *obj*.  Raises the first problem found, checking each field
    in schema order: MissingField → BadType → BadValue.
    """
    result = {}

    for name, spec in schema.items():
        required = spec.get("required", False)
        expected_type = spec.get("type")
        default = spec.get("default", None)
        choices = spec.get("choices")

        # --- presence check ---
        if name not in obj:
            if required:
                raise MissingField(f"missing required field: {name!r}")
            result[name] = default
            continue

        value = obj[name]

        # --- type check ---
        if expected_type is not None:
            if not _matches_type(value, expected_type):
                raise BadType(
                    f"field {name!r}: expected {expected_type}, "
                    f"got {type(value).__name__}"
                )

        # --- value-constraint check ---
        if choices is not None:
            if value not in choices:
                raise BadValue(
                    f"field {name!r}: value {value!r} not in {choices!r}"
                )

        # --- coerce & store ---
        result[name] = _coerce(value, expected_type)

    return result
```

