from collections import deque

from vp.errors import ValidationError
from vp.validate import validate


class RequestQueue:
    """A validated FIFO request queue."""

    def __init__(self, schema):
        self.schema = schema
        self._queue = deque()

    def submit(self, obj):
        """Validate *obj* against the queue's schema.

        On success the coerced dict is enqueued and returned.
        On failure the appropriate ValidationError subclass is raised and
        nothing is enqueued.
        """
        coerced = validate(obj, self.schema)
        self._queue.append(coerced)
        return coerced

    @property
    def pending(self):
        """Number of requests waiting in the queue."""
        return len(self._queue)

    def drain(self):
        """Return all pending requests in FIFO order and empty the queue."""
        items = list(self._queue)
        self._queue.clear()
        return items
