"""tindex/builder.py – incremental inverted-index builder."""

from collections import defaultdict


def _tokenize(text):
    """Yield (word, 0-based position) pairs for whitespace-delimited text."""
    for i, word in enumerate(text.split()):
        yield word, i


def build(pairs, chunk=64):
    """Generator yielding batches of postings entries.

    *pairs* is an iterable of ``(doc_id, text)``.  Documents are grouped in
    chunks of *chunk*; a batch (list of ``(term, doc_id, positions)`` tuples)
    is yielded as soon as its chunk is full.  The final batch may be shorter.

    Memory: at most one chunk of raw text is held at a time.
    """
    buf = []
    for doc_id, text in pairs:
        buf.append((doc_id, text))
        if len(buf) == chunk:
            yield _process_chunk(buf)
            buf = []
    if buf:
        yield _process_chunk(buf)


def _process_chunk(docs):
    """Turn a list of (doc_id, text) into a list of postings entries."""
    postings = []
    for doc_id, text in docs:
        term_positions = defaultdict(list)
        for word, pos in _tokenize(text):
            term_positions[word].append(pos)
        for term, positions in term_positions.items():
            postings.append((term, doc_id, positions))
    return postings


def merge(base, extra):
    """Merge postings entries *extra* into *base* in place.

    *base* is a dict ``term -> {doc_id: [positions]}``.
    *extra* is a list of ``(term, doc_id, positions)`` tuples.

    Position lists are unioned, de-duplicated, and sorted.  Returns *base*.
    """
    for term, doc_id, positions in extra:
        if term not in base:
            base[term] = {}
        if doc_id not in base[term]:
            base[term][doc_id] = []
        base[term][doc_id].extend(positions)
        base[term][doc_id] = sorted(set(base[term][doc_id]))
    return base


class Index:
    """In-memory inverted index."""

    def __init__(self):
        self._index = {}  # term -> {doc_id: [positions]}
        self._doc_count = 0

    @property
    def doc_count(self):
        return self._doc_count

    def terms(self):
        """Return the list of indexed terms."""
        return list(self._index.keys())

    def rebuild(self, pairs):
        """Replace the index with a fresh build from *pairs*.

        Returns the total number of postings (sum of every position-list length).
        """
        self._index = {}
        self._doc_count = 0
        for batch in build(pairs):
            merge(self._index, batch)
        total = 0
        seen_docs = set()
        for postings in self._index.values():
            for doc_id, positions in postings.items():
                seen_docs.add(doc_id)
                total += len(positions)
        self._doc_count = len(seen_docs)
        return total

    def lookup(self, term):
        """Return a sorted list of doc-ids containing *term*."""
        if term not in self._index:
            return []
        return sorted(self._index[term].keys())
