class Runner:
    def __init__(self, max_per_tenant=2):
        self._max_per_tenant = max_per_tenant
        self._queue = []
        self._seq = 0
        self._last_tenant = None
        self._consecutive = 0
        self._run_count = 0
        self._failed_count = 0

    def submit(self, tenant, fn, *, priority=0):
        self._queue.append((priority, self._seq, tenant, fn))
        self._seq += 1

    def _pick_next(self):
        if not self._queue:
            return None

        ineligible = None
        if self._last_tenant is not None and self._consecutive >= self._max_per_tenant:
            ineligible = self._last_tenant

        eligible = [j for j in self._queue if j[2] != ineligible]

        if not eligible:
            eligible = list(self._queue)

        eligible.sort(key=lambda j: (-j[0], j[1]))
        return eligible[0]

    def run(self, limit=None):
        results = []
        count = 0
        while (limit is None or count < limit) and self._queue:
            job = self._pick_next()
            if job is None:
                break
            priority, seq, tenant, fn = job
            self._queue.remove(job)

            try:
                result = fn()
                results.append({'ok': True, 'result': result})
            except Exception as e:
                results.append({'ok': False, 'error': str(e)})
                self._failed_count += 1

            self._run_count += 1
            count += 1

            if tenant == self._last_tenant:
                self._consecutive += 1
            else:
                self._last_tenant = tenant
                self._consecutive = 1

        return results

    def stats(self):
        return {
            'run': self._run_count,
            'failed': self._failed_count,
            'skipped': len(self._queue),
        }

    def pending(self):
        return len(self._queue)

    def reset(self):
        self._queue.clear()
        self._last_tenant = None
        self._consecutive = 0
