import heapq

from mig.errors import MigrationError


def plan(migrations):
    """Return migration names in dependency order. Ties broken alphabetically.

    Raises MigrationError on a missing dependency or a cycle.
    """
    by_name = {m["name"]: m for m in migrations}

    for m in migrations:
        for dep in m.get("deps", []):
            if dep not in by_name:
                raise MigrationError(
                    f"Missing dependency: '{dep}' required by '{m['name']}'"
                )

    in_degree = {name: 0 for name in by_name}
    dependents = {name: [] for name in by_name}

    for m in migrations:
        for dep in m.get("deps", []):
            in_degree[m["name"]] += 1
            dependents[dep].append(m["name"])

    heap = [name for name, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        name = heapq.heappop(heap)
        result.append(name)
        for dependent in dependents[name]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(by_name):
        raise MigrationError("Dependency cycle detected")

    return result


