from __future__ import annotations

from typing import Any, Callable, Iterable, Iterator, Tuple


class Windowed:
    """Yield (key, result) for every complete non-overlapping window of *size* items per key.

    Parameters
    ----------
    source : iterable
        * If *key* is ``None``: yields plain values; all are grouped under key ``None``.
        * If *key* is a callable: yields ``(key, value)`` pairs; *key(item)* extracts the
          grouping key from each pair.
    size : int
        Number of values per window.  Must be > 0.
    fn : callable
        Called with the list of values (oldest first) in a complete window; returns the
        aggregate result.
    key : callable | None
        ``None`` → single implicit key.  Otherwise a callable applied to each source item.
    """

    _peak_memory: int = 0

    def __init__(
        self,
        source: Iterable,
        size: int,
        fn: Callable[[list], Any],
        key: Callable | None = None,
    ) -> None:
        if size <= 0:
            raise ValueError(f"size must be a positive integer, got {size!r}")
        self.source = source
        self.size = size
        self.fn = fn
        self.key = key
        self._buffers: dict[Any, list] = {}

    # ------------------------------------------------------------------
    def __iter__(self) -> Iterator[Tuple[Any, Any]]:
        for item in self.source:
            if self.key is None:
                k: Any = None
                value = item
            else:
                k = self.key(item)
                value = item[1]

            buf = self._buffers.get(k)
            if buf is None:
                buf = []
                self._buffers[k] = buf

            buf.append(value)

            if len(buf) > Windowed._peak_memory:
                Windowed._peak_memory = len(buf)

            if len(buf) == self.size:
                result = self.fn(buf)
                yield (k, result)
                self._buffers[k] = []

    # ------------------------------------------------------------------
    @classmethod
    def peak_memory(cls) -> int:
        """Largest number of values ever held for any single key."""
        return cls._peak_memory


def summarise(
    source: Iterable,
    size: int,
    fn: Callable[[list], Any],
    key: Callable | None = None,
) -> list:
    """Convenience: return a list of all window results."""
    return [result for _, result in Windowed(source, size, fn, key)]
