        self.is_word = False


class Trie:
    def __init__(self):
        self._root = _TrieNode()
        self._size = 0

    # ------------------------------------------------------------------
    # insert / remove
    # ------------------------------------------------------------------
    def insert(self, word, weight=1):
        word = word.lower()
        node = self._root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = _TrieNode()
            node = node.children[ch]
        if not node.is_word:
            self._size += 1
        node.is_word = True
        node.weight = weight

    def remove(self, word):
        word = word.lower()
        path = []
        node = self._root
        for ch in word:
            if ch not in node.children:
                return
            path.append((node, ch))
            node = node.children[ch]
        if not node.is_word:
            return
        node.is_word = False
        node.weight = 0
        self._size -= 1
        for parent, ch in reversed(path):
            child = parent.children[ch]
            if not child.children and not child.is_word:
                del parent.children[ch]
            else:
                break

    # ------------------------------------------------------------------
    # completion
    # ------------------------------------------------------------------
    def complete(self, prefix, limit=10):
        prefix = prefix.lower()
        node = self._root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        results = []
        self._collect(node, prefix, results)
        results.sort(key=lambda x: (-x[1], x[0]))
        if limit is None or limit == 0:
            return [w for w, _ in results]
        return [w for w, _ in results[:limit]]

    def _collect(self, node, prefix, results):
        if node.is_word:
            results.append((prefix, node.weight))
        for ch in sorted(node.children):
            self._collect(node.children[ch], prefix + ch, results)

    # ------------------------------------------------------------------
    # weight update
    # ------------------------------------------------------------------
    def update_weight(self, word, delta):
        word = word.lower()
        node = self._root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = _TrieNode()
            node = node.children[ch]
        if not node.is_word:
            node.is_word = True
            node.weight = delta
            self._size += 1
        else:
            node.weight += delta

    # ------------------------------------------------------------------
    # dunder helpers
    # ------------------------------------------------------------------
    def __contains__(self, word):
        word = word.lower()
        node = self._root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_word

    def __len__(self):
        return self._size

    # ------------------------------------------------------------------
    # longest_prefix_of
    # ------------------------------------------------------------------
    def longest_prefix_of(self, text):
        text = text.lower()
        node = self._root
        best = None
        current = []
        for ch in text:
            if ch not in node.children:
                break
            node = node.children[ch]
            current.append(ch)
            if node.is_word:
                best = "".join(current)
        return best

    # ------------------------------------------------------------------
    # words
    # ------------------------------------------------------------------
    def words(self):
        results = []
        self._collect_words(self._root, [], results)
        results.sort()
        return results

    def _collect_words(self, node, prefix, results):
