from dataclasses import dataclass
from typing import Any, Callable, Iterable, List, Optional, Tuple


@dataclass
class BatchStats:
    processed: int
    failed: int


def chunked(source: Iterable, size: int):
    if size <= 0:
        raise ValueError(f"size must be positive, got {size}")
    chunk: list = []
    for item in source:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk


def run_batches(
    source: Iterable,
    fn: Callable,
    size: int,
    on_error: Optional[Callable] = None,
) -> Tuple[List[Any], BatchStats]:
    results: List[Any] = []
    processed = 0
    failed = 0
    for chunk in chunked(source, size):
        try:
            result = fn(chunk)
            results.append(result)
            processed += 1
        except Exception as exc:
            results.append(None)
            failed += 1
            if on_error is not None:
                on_error(chunk, exc)
    return (results, BatchStats(processed, failed))
