import time
from typing import Any, Callable, Optional


class Cache:
    def __init__(self, get_clock: Optional[Callable[[], float]] = None, default_ttl: Optional[float] = None):
        self._clock = get_clock if get_clock is not None else time.monotonic
        self._default_ttl = default_ttl
        self._store: dict[Any, tuple[Any, Optional[float]]] = {}

    def put(self, key: Any, value: Any, ttl: Optional[float] = None) -> None:
        if ttl is None:
            ttl = self._default_ttl
        if ttl is None:
            expiry: Optional[float] = None
        else:
            expiry = self._clock() + ttl
        self._store[key] = (value, expiry)

    def _is_expired(self, key: Any) -> bool:
        if key not in self._store:
            return True
        _, expiry = self._store[key]
        if expiry is None:
            return False
        return self._clock() >= expiry

    def get(self, key: Any) -> Any:
        if key not in self._store:
            return None
        value, expiry = self._store[key]
        if expiry is not None and self._clock() >= expiry:
            del self._store[key]
            return None
        return value

    def get_or_set(self, key: Any, factory: Callable[[], Any], ttl: Optional[float] = None) -> Any:
        if key in self._store:
            value, expiry = self._store[key]
            if expiry is None or self._clock() < expiry:
                return value
            del self._store[key]
        value = factory()
        self.put(key, value, ttl)
        return value

    def delete(self, key: Any) -> None:
        self._store.pop(key, None)

    def __len__(self) -> int:
        return sum(1 for key in self._store if not self._is_expired(key))

    def __contains__(self, key: Any) -> bool:
        return key in self._store and not self._is_expired(key)

    def purge(self) -> int:
        expired = [key for key in self._store if self._is_expired(key)]
        for key in expired:
            del self._store[key]
        return len(expired)

    def keys(self) -> list:
        return sorted(key for key in self._store if not self._is_expired(key))
