import os
from pathlib import Path


class Worker:
    def __init__(self, model, shards, out_dir, checkpoint_every=10):
        if hasattr(model, "load_count"):
            assert model.load_count == 1, "model must be loaded exactly once"
        self.model = model
        self.shards = shards
        self.out_dir = Path(out_dir)
        self.checkpoint_every = checkpoint_every
        self.total_inferred = 0
        self._skipped_this_call = 0
        self.out_dir.mkdir(parents=True, exist_ok=True)

    # ------------------------------------------------------------------
    # helpers
    # ------------------------------------------------------------------
    def _done_path(self):
        return self.out_dir / "done.txt"

    def _failed_path(self):
        return self.out_dir / "failed.txt"

    def _read_done(self):
        p = self._done_path()
        if p.exists():
            return set(
                line.strip() for line in p.read_text().splitlines() if line.strip()
            )
        return set()

    def _read_failed(self):
        p = self._failed_path()
        if p.exists():
            return set(
                line.strip() for line in p.read_text().splitlines() if line.strip()
            )
        return set()

    def _append_done(self, shard_id):
        with open(self._done_path(), "a") as f:
            f.write(f"{shard_id}\n")

    def _append_failed(self, shard_id):
        with open(self._failed_path(), "a") as f:
            f.write(f"{shard_id}\n")

    def _remove_failed(self, shard_id):
        p = self._failed_path()
        if p.exists():
            lines = [l.strip() for l in p.read_text().splitlines() if l.strip()]
            lines = [l for l in lines if l != shard_id]
            p.write_text("\n".join(lines) + ("\n" if lines else ""))

    def _flush_buffer(self, buffer):
        with open(self._done_path(), "a") as f:
            for sid in buffer:
                f.write(f"{sid}\n")

    @staticmethod
    def _shard_id(shard):
        if isinstance(shard, dict):
            return shard["id"]
        return shard.id

    @staticmethod
    def _shard_text(shard):
        if isinstance(shard, dict):
            return shard["text"]
        return shard.text

    # ------------------------------------------------------------------
    # public API
    # ------------------------------------------------------------------
    def run(self):
        done_ids = self._read_done()
        buffer = []
        completed_since_flush = 0

        for shard in self.shards:
            shard_id = self._shard_id(shard)

            # Resume: skip shards already completed in a previous run
            if shard_id in done_ids:
                output_file = self.out_dir / f"{shard_id}.txt"
                if output_file.exists():
                    self._skipped_this_call += 1
                    continue

            # Infer
            text = self._shard_text(shard)
            self.total_inferred += 1
            try:
                result = self.model.infer(text)
            except Exception:
                self._append_failed(shard_id)
                continue

            # Write output
            output_file = self.out_dir / f"{shard_id}.txt"
            output_file.write_text(result)

            # Buffer for checkpoint
            buffer.append(shard_id)
            completed_since_flush += 1

            if completed_since_flush >= self.checkpoint_every:
                self._flush_buffer(buffer)
                buffer = []
                completed_since_flush = 0

        # Always flush remaining at the end
        if buffer:
            self._flush_buffer(buffer)

    def stats(self):
        done_ids = self._read_done()
        failed_ids = self._read_failed()

        done_count = 0
        for shard in self.shards:
            shard_id = self._shard_id(shard)
            if shard_id in done_ids:
                output_file = self.out_dir / f"{shard_id}.txt"
                if output_file.exists():
                    done_count += 1

        return {
            "total": len(self.shards),
            "done": done_count,
            "skipped": self._skipped_this_call,
            "failed": len(failed_ids),
        }

    def retry_failed(self):
        failed_ids = self._read_failed()
        if not failed_ids:
            return 0

        shard_map = {}
        for shard in self.shards:
            shard_map[self._shard_id(shard)] = shard

        successes = 0
        for shard_id in list(failed_ids):
            if shard_id not in shard_map:
                continue
            shard = shard_map[shard_id]
            text = self._shard_text(shard)

            self.total_inferred += 1
            try:
                result = self.model.infer(text)
            except Exception:
                # Still failed – stays in failed.txt, not counted
                continue

            # Success: write output, record in done, remove from failed
            output_file = self.out_dir / f"{shard_id}.txt"
            output_file.write_text(result)
            self._append_done(shard_id)
            self._remove_failed(shard_id)
            successes += 1

        return successes
