DROP = _DropType()


# ─── internal helpers ────────────────────────────────────────────────────────

def _deep_copy(obj):
    """Recursively copy dicts / lists / tuples; everything else via copy.deepcopy."""
    if isinstance(obj, Mapping):
        return {k: _deep_copy(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_deep_copy(item) for item in obj]
    if isinstance(obj, tuple):
        return tuple(_deep_copy(item) for item in obj)
    return copy.deepcopy(obj)


def _remove_nested(cfg, dotted_key):
    """Remove *dotted_key* from *cfg* (in-place on an already-copied dict)."""
    keys = dotted_key.split(".")
    node = cfg
    for k in keys[:-1]:
        if isinstance(node, Mapping) and k in node:
            node = node[k]
        else:
            return
    if isinstance(node, Mapping):
        node.pop(keys[-1], None)


def _set_nested(cfg, dotted_key, value):
    """Set *dotted_key* in *cfg* (in-place), creating intermediate dicts."""
    keys = dotted_key.split(".")
    node = cfg
    for k in keys[:-1]:
        if k not in node or not isinstance(node[k], dict):
            node[k] = {}
        node = node[k]
    node[keys[-1]] = value


