    """Merge *layer* (a Mapping) into *base* (a mutable dict copy). Mutates *base*."""
    for key, value in layer.items():
        # ── dotted-path key in a layer ──────────────────────────────────
        if isinstance(key, str) and "." in key:
            if value is DROP:
                _remove_nested(base, key)
            else:
                _set_nested(base, key, _deep_copy(value))
            continue

        # ── DROP sentinel ───────────────────────────────────────────────
        if value is DROP:
            base.pop(key, None)
            continue

        # ── key already present in base ─────────────────────────────────
        if key in base:
            base_val = base[key]

            if isinstance(base_val, dict) and isinstance(value, Mapping):
                _merge_into(base_val, value, lists_mode)

            elif isinstance(base_val, list) and isinstance(value, list):
                if lists_mode == "replace":
                    base[key] = _deep_copy(value)
                elif lists_mode == "concat":
                    base[key] = base_val + _deep_copy(value)
                elif lists_mode == "unique":
                    combined = base_val + _deep_copy(value)
                    seen = []
                    deduped = []
                    for item in combined:
                        if item not in seen:
                            seen.append(item)
                            deduped.append(item)
                    base[key] = deduped
            else:
                base[key] = _deep_copy(value)
        else:
            base[key] = _deep_copy(value)

    return base


# ─── public API ──────────────────────────────────────────────────────────────

def merge(base, *layers, lists="replace"):
    """Merge *base* with positional *layers*.  Never mutates *base* or any layer.

    Parameters
    ----------
    lists : {'replace', 'concat', 'unique'}
        How to combine list values that appear in multiple layers.
    """
    if lists not in ("replace", "concat", "unique"):
        raise ValueError(
            f"lists must be 'replace', 'concat', or 'unique'; got {lists!r}"
        )

    result = _deep_copy(base)

    for layer in layers:
        if isinstance(layer, Mapping):
            _merge_into(result, layer, lists)
        else:
            # Non-mapping layer replaces the whole accumulated config.
            result = _deep_copy(layer)

    return result


def deep_get(cfg, path, default=None):
    """Read a dotted path from *cfg*.  Returns *default* if any segment is missing."""
    keys = path.split(".")
    node = cfg
    for k in keys:
        if isinstance(node, Mapping) and k in node:
            node = node[k]
        else:
            return default
    return node


